import java.io.*;import java.nio.file.*;import java.util.*;
import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;import com.jpexs.decompiler.flash.tags.base.*;import com.jpexs.decompiler.flash.types.*;import com.jpexs.decompiler.flash.types.shaperecords.*;
/** Cosmetic blood-free variant. No ActionScript, frame count or rule constants are changed. */
public class Nonviolent {
 static SWF swf;static List<String> audit=new ArrayList<>();
 static void replace(Tag old,Tag t){swf.replaceTag(old,t);t.setModified(true);swf.updateCharacters();}
 static ShapeTag shape(int id){return (ShapeTag)swf.getCharacter(id);}
 static void empty(int id){ShapeTag old=shape(id);DefineShape3Tag s=new DefineShape3Tag(swf);s.shapeId=id;s.shapeBounds=old.shapeBounds;s.shapes=SHAPEWITHSTYLE.createEmpty(3);replace(old,s);audit.add(id+"\tblank-blood-vector");}
 static void edge(SHAPEWITHSTYLE sh,int dx,int dy){StraightEdgeRecord e=new StraightEdgeRecord();e.deltaX=dx;e.deltaY=dy;e.generalLineFlag=dx!=0&&dy!=0;e.vertLineFlag=dx==0;e.calculateBits();sh.shapeRecords.add(e);}
 static void polygon(SHAPEWITHSTYLE sh,int[][] points,int style){StyleChangeRecord m=new StyleChangeRecord();m.stateMoveTo=true;m.moveDeltaX=points[0][0];m.moveDeltaY=points[0][1];m.stateFillStyle1=true;m.fillStyle1=style;m.calculateBits();sh.shapeRecords.add(m);for(int i=1;i<=points.length;i++){int[] a=points[(i-1)%points.length],b=points[i%points.length];edge(sh,b[0]-a[0],b[1]-a[1]);}}
 static FILLSTYLE solid(int r,int g,int b){FILLSTYLE f=new FILLSTYLE();f.fillStyleType=FILLSTYLE.SOLID;f.color=new RGBA(r,g,b,255);return f;}
 static int[][] burst(RECT b,double scale){int[][] p=new int[24][2];double cx=(b.Xmin+b.Xmax)/2.,cy=(b.Ymin+b.Ymax)/2.;for(int i=0;i<p.length;i++){double a=-Math.PI/2+i*Math.PI/12,rad=(i%2==0?1:.66)*scale;p[i][0]=(int)Math.round(cx+Math.cos(a)*(b.Xmax-b.Xmin)/2.*rad);p[i][1]=(int)Math.round(cy+Math.sin(a)*(b.Ymax-b.Ymin)/2.*rad);}return p;}
 static int[][] arrow(RECT b,double scale){double[][] uv={{.02,.28},{.6,.28},{.6,.02},{.98,.5},{.6,.98},{.6,.72},{.02,.72}};int[][] p=new int[uv.length][2];double cx=(b.Xmin+b.Xmax)/2.,cy=(b.Ymin+b.Ymax)/2.;for(int i=0;i<p.length;i++){p[i][0]=(int)Math.round(cx+(uv[i][0]-.5)*(b.Xmax-b.Xmin)*scale);p[i][1]=(int)Math.round(cy+(uv[i][1]-.5)*(b.Ymax-b.Ymin)*scale);}return p;}
 static void comic(int id,boolean isArrow){ShapeTag old=shape(id);DefineShape3Tag s=new DefineShape3Tag(swf);s.shapeId=id;s.shapeBounds=old.shapeBounds;SHAPEWITHSTYLE sh=SHAPEWITHSTYLE.createEmpty(3);sh.fillStyles.fillStyles=new FILLSTYLE[]{solid(30,20,40),solid(255,211,56)};sh.shapeRecords=new ArrayList<>();polygon(sh,isArrow?arrow(s.shapeBounds,1):burst(s.shapeBounds,1),1);polygon(sh,isArrow?arrow(s.shapeBounds,.85):burst(s.shapeBounds,.85),2);sh.shapeRecords.add(new EndShapeRecord());s.shapes=sh;replace(old,s);audit.add(id+"\t"+(isArrow?"comic-direction-arrow":"gold-comic-combo-burst"));}
 static void cleanMixedArt(int id,int imageId,Path file)throws Exception{
  ShapeTag old=shape(id);RECT b=old.shapeBounds;var pixels=javax.imageio.ImageIO.read(file.toFile());
  DefineBitsLossless2Tag image=new DefineBitsLossless2Tag(swf);image.setCharacterId(imageId);image.setImage(Files.readAllBytes(file));swf.addTag(swf.indexOfTag(old),image);
  DefineShape3Tag t=new DefineShape3Tag(swf);t.shapeId=id;t.shapeBounds=b;SHAPEWITHSTYLE sh=SHAPEWITHSTYLE.createEmpty(3);sh.shapeRecords=new ArrayList<>();
  FILLSTYLE f=new FILLSTYLE();f.fillStyleType=FILLSTYLE.CLIPPED_BITMAP;f.bitmapId=imageId;f.bitmapMatrix=new MATRIX();f.bitmapMatrix.hasScale=true;f.bitmapMatrix.scaleX=(float)(b.Xmax-b.Xmin)/pixels.getWidth();f.bitmapMatrix.scaleY=(float)(b.Ymax-b.Ymin)/pixels.getHeight();f.bitmapMatrix.translateX=b.Xmin;f.bitmapMatrix.translateY=b.Ymin;sh.fillStyles.fillStyles=new FILLSTYLE[]{f};
  polygon(sh,new int[][]{{b.Xmin,b.Ymin},{b.Xmax,b.Ymin},{b.Xmax,b.Ymax},{b.Xmin,b.Ymax}},1);sh.shapeRecords.add(new EndShapeRecord());t.shapes=sh;replace(old,t);audit.add(id+"\timagegen-repaired-mixed-blood-art; new texture="+imageId);
 }
 static void collapsedBoss()throws Exception{ShapeTag old=shape(1870),safe=(ShapeTag)shape(436).cloneTag();RECT from=safe.shapeBounds,to=old.shapeBounds;double sx=(double)(to.Xmax-to.Xmin)/(from.Xmax-from.Xmin),sy=(double)(to.Ymax-to.Ymin)/(from.Ymax-from.Ymin);var sh=safe.getShapes().resize(sx,sy);int dx=to.Xmin-(int)Math.round(from.Xmin*sx),dy=to.Ymin-(int)Math.round(from.Ymin*sy);for(var r:sh.shapeRecords)if(r instanceof StyleChangeRecord sc&&sc.stateMoveTo){sc.moveDeltaX+=dx;sc.moveDeltaY+=dy;sc.calculateBits();}safe.setCharacterId(1870);safe.shapeBounds=to;safe.shapes=sh;replace(old,safe);audit.add("1870\tintact-knocked-out-boss-from-original-436");}
 static void intactDeath(){DefineSpriteTag sp=(DefineSpriteTag)swf.getCharacter(369);int frame=1,count=0;for(Tag t:new ArrayList<Tag>(sp.getTags().toArrayList())){if(t instanceof ShowFrameTag)frame++;else if(frame>=25&&(t instanceof PlaceObjectTypeTag||t instanceof RemoveObjectTag||t instanceof RemoveObject2Tag)){sp.removeTag(t);count++;}}sp.setModified(true);audit.add("369\tretain-intact-pose-from-frame-24; remove "+count+" shard placements/removals; retain frame-25 damage and frame-97 gameover callbacks");}
 public static void main(String[]a)throws Exception{swf=new SWF(new FileInputStream(a[0]),false);Path art=Path.of(a[2]);for(int id:new int[]{393,394,395,396,397,398,399,842,843,844,845,846,847,848})empty(id);comic(1746,false);for(int id:new int[]{1844,1847,1848,1849,1851,1852,1853,1854,1855,1856})comic(id,true);cleanMixedArt(1202,7000,art.resolve("runtime/1211.png"));cleanMixedArt(1204,7001,art.resolve("runtime/1213.png"));collapsedBoss();intactDeath();
 for(int id:new int[]{1211,1213,2036}){CharacterTag old=swf.getCharacter(id);DefineBitsLossless2Tag img=new DefineBitsLossless2Tag(swf);img.setCharacterId(id);img.setImage(Files.readAllBytes(art.resolve("runtime/"+id+".png")));replace(old,img);audit.add(id+"\timagegen-clean-blood-stains");}
 Files.write(art.resolve("symbol-audit.tsv"),audit);try(var out=new FileOutputStream(a[1])){swf.saveTo(out);}System.out.println("Blood-free cosmetic operations="+audit.size());System.exit(0);}
}
